const today = new Date().toISOString().split('T')[0];
const todayDate = new Date();
const nextWeek = new Date(Date.now() + 7*86400000).toISOString().split('T')[0];
const dayOfWeek = todayDate.getDay();
const daysToMonday = dayOfWeek === 0 ? 6 : dayOfWeek - 1;
const monday = new Date(todayDate.getTime() - daysToMonday * 86400000);
const weekOf = monday.toISOString().split('T')[0];

let mtl = '';
try {
  const buf = await this.helpers.getBinaryDataBuffer(0, 'data');
  mtl = buf.toString('utf-8');
} catch(e) {}

const areas = ['faith','family','business','consulting','work','health','home','personal'];
const areaEmoji = { faith:'🙏', family:'👨‍👩‍👧', business:'🚀', consulting:'💼', work:'🏥', health:'💪', home:'🏠', personal:'🎯' };

const stats = {};
for (const a of areas) stats[a] = { total: 0, completed: 0, overdue: 0, dueThisWeek: 0, noDue: 0, priorityA: 0, priorityADone: 0, priorityAOpen: 0 };

const overdueTasks = [];
const undatedARocks = [];

const openRe = /^- \[ \] (.+?)\[area:: (\w+)\].*?\[priority:: ([ABC])\](?:.*?\[due:: (\d{4}-\d{2}-\d{2})\])?/gm;
let m;
while ((m = openRe.exec(mtl)) !== null) {
  const [, descRaw, area, priority, due] = m;
  if (!stats[area]) continue;
  const desc = descRaw.trim();
  stats[area].total++;
  if (priority === 'A') {
    stats[area].priorityA++;
    stats[area].priorityAOpen++;
    if (!due) undatedARocks.push({ desc, area });
  }
  if (!due) {
    stats[area].noDue++;
  } else {
    if (due < today) {
      const daysOverdue = Math.floor((new Date(today) - new Date(due)) / 86400000);
      stats[area].overdue++;
      overdueTasks.push({ desc, area, priority, due, daysOverdue });
    }
    if (due >= today && due <= nextWeek) stats[area].dueThisWeek++;
  }
}

const doneRe = /^- \[x\] (.+?)\[area:: (\w+)\].*?\[priority:: ([ABC])\]/gm;
while ((m = doneRe.exec(mtl)) !== null) {
  const [, , area, priority] = m;
  if (!stats[area]) continue;
  stats[area].completed++;
  if (priority === 'A') stats[area].priorityADone++;
}

// Tier overdue
const critical = overdueTasks.filter(t => t.daysOverdue >= 8);
const high = overdueTasks.filter(t => t.daysOverdue >= 4 && t.daysOverdue < 8);
const medium = overdueTasks.filter(t => t.daysOverdue < 4);

// Q2 rocks — dynamic, hide rocks with total === 0
const ROCKS = [
  { area:'faith', label:'Social media Bible study (4 sessions)' },
  { area:'family', label:'Marriage Alignment + bi-weekly check-in' },
  { area:'business', label:'MVP — website, offer, 3 outreach (Echelon Seven)' },
  { area:'work', label:'Deliver Union project + position for exit' },
  { area:'health', label:'Hip decision + 3x/week gym ×8 weeks' },
];
const liveRocks = ROCKS.map(r => {
  const done = stats[r.area].priorityADone;
  const open = stats[r.area].priorityAOpen;
  const total = done + open;
  const pct = total > 0 ? Math.round((done / total) * 100) : 0;
  return Object.assign({}, r, { done, open, total, pct });
}).filter(r => r.total > 0);

// === Subject spoiler ===
let subject;
if (undatedARocks.length > 0) {
  subject = `📊 Weekly Review — ${undatedARocks.length} Priority A rock${undatedARocks.length > 1 ? 's need' : ' needs'} dates · ${overdueTasks.length} overdue`;
} else if (critical.length > 0) {
  subject = `🔥 Weekly Review — ${critical.length} CRITICAL overdue (8d+) · need to triage now`;
} else if (overdueTasks.length > 0) {
  subject = `📊 Weekly Review — ${overdueTasks.length} overdue · ${liveRocks.length} rocks in flight`;
} else {
  const totalDone = areas.reduce((s, a) => s + stats[a].completed, 0);
  subject = `✅ Weekly Review — All clear · ${totalDone} done in MTL · Week of ${weekOf}`;
}

// === HTML build ===
function priorityBadge(p) {
  const colors = { A:'#dc2626', B:'#d97706', C:'#6b7280' };
  return '<span style="display:inline-block;padding:2px 6px;border-radius:3px;font-size:10px;font-weight:bold;background:' + colors[p] + ';color:white">' + p + '</span>';
}

function progressBar(pct, color) {
  const c = color || (pct >= 75 ? '#16a34a' : pct >= 40 ? '#d97706' : '#dc2626');
  return '<div style="background:#e5e7eb;border-radius:4px;height:6px;margin-top:4px"><div style="background:' + c + ';width:' + pct + '%;height:6px;border-radius:4px"></div></div>';
}

let html = '<div style="font-family:-apple-system,BlinkMacSystemFont,\'Segoe UI\',Arial,sans-serif;max-width:680px;margin:0 auto;background:#f5f5f5;padding:0;color:#1a1a1a;line-height:1.5">';

// Apple Watch / accessibility preview
const previewLine = `Week of ${weekOf} · ${overdueTasks.length} overdue · ${undatedARocks.length} A rocks need dates · ${liveRocks.length} rocks tracked`;
html += '<noscript style="display:block;padding:8px 16px;background:#f3f4f6;color:#1f2937;font-size:12px">' + previewLine + '</noscript>';

// Header
html += '<div style="background:#1a1a2e;color:white;padding:22px 20px;border-radius:8px 8px 0 0">';
html += '<h1 style="margin:0;font-size:20px;font-weight:700">📊 Weekly Life OS Review</h1>';
html += '<p style="margin:6px 0 0;font-size:13px;opacity:0.85">Week of ' + weekOf + ' · ' + today + '</p>';
html += '</div>';

// === FOCUS — the only true CTA ===
html += '<div style="background:#7c3aed;color:white;padding:14px 20px;margin:2px 0">';
html += '<p style="margin:0;font-size:10px;text-transform:uppercase;letter-spacing:1.5px;opacity:0.85">🎯 FOCUS FOR THIS WEEK</p>';
if (undatedARocks.length === 0) {
  html += '<p style="margin:6px 0 0;font-size:14px;font-weight:600">All Priority A rocks have dates scheduled. ✅</p>';
} else {
  html += '<p style="margin:6px 0 4px;font-size:14px;font-weight:600">Schedule a due date for these ' + undatedARocks.length + ' Priority A rock' + (undatedARocks.length > 1 ? 's' : '') + ':</p>';
}
html += '</div>';

if (undatedARocks.length > 0) {
  html += '<div style="padding:14px 20px;background:white">';
  for (const r of undatedARocks.slice(0, 8)) {
    const emoji = areaEmoji[r.area] || '📌';
    html += '<div style="border-left:4px solid #7c3aed;background:#f5f3ff;padding:10px 14px;margin:6px 0;border-radius:0 4px 4px 0">';
    html += priorityBadge('A') + ' <span style="font-size:13px;font-weight:500;margin-left:6px">' + emoji + ' ' + r.desc + '</span>';
    html += '<div style="font-size:11px;color:#6b21a8;margin-top:4px;text-transform:capitalize">' + r.area + ' · needs due date</div>';
    html += '</div>';
  }
  if (undatedARocks.length > 8) {
    html += '<p style="margin:8px 0 0;font-size:11px;color:#6b7280">…and ' + (undatedARocks.length - 8) + ' more in MTL.</p>';
  }
  html += '</div>';
}

// === HEALTH ALERT — tiered, tight ===
html += '<div style="padding:14px 20px;background:#fff8f8;margin-top:2px">';
html += '<h2 style="margin:0 0 10px;font-size:14px;color:#dc2626;font-weight:700;text-transform:uppercase;letter-spacing:1.5px">🔥 Overdue Health</h2>';
if (overdueTasks.length === 0) {
  html += '<div style="background:#f0fdf4;border:1px solid #86efac;border-radius:4px;padding:12px;text-align:center"><span style="color:#14532d;font-weight:600">✅ Zero overdue tasks. Caught up!</span></div>';
} else {
  html += '<table style="width:100%;border-collapse:collapse;font-size:13px">';
  html += '<tr><td style="padding:8px 12px;background:#fef2f2;border-left:4px solid #dc2626"><strong style="color:#991b1b">🔴 CRITICAL (8+ days)</strong></td><td style="padding:8px 12px;text-align:right;background:#fef2f2"><strong style="font-size:18px;color:#991b1b">' + critical.length + '</strong></td></tr>';
  html += '<tr><td style="padding:8px 12px;background:#fff7ed;border-left:4px solid #ea580c"><strong style="color:#9a3412">🟠 HIGH (4-7 days)</strong></td><td style="padding:8px 12px;text-align:right;background:#fff7ed"><strong style="font-size:18px;color:#9a3412">' + high.length + '</strong></td></tr>';
  html += '<tr><td style="padding:8px 12px;background:#fffbeb;border-left:4px solid #d97706"><strong style="color:#92400e">🟡 MEDIUM (1-3 days)</strong></td><td style="padding:8px 12px;text-align:right;background:#fffbeb"><strong style="font-size:18px;color:#92400e">' + medium.length + '</strong></td></tr>';
  html += '</table>';

  // Show critical task list inline (if any) — these need triage NOW
  if (critical.length > 0) {
    html += '<p style="margin:12px 0 4px;font-size:12px;font-weight:600;color:#991b1b">Critical tasks (8+ days overdue):</p>';
    for (const t of critical.slice(0, 5)) {
      const emoji = areaEmoji[t.area] || '📌';
      html += '<div style="border-left:3px solid #dc2626;background:#fef2f2;padding:8px 12px;margin:4px 0;font-size:12px">';
      html += priorityBadge(t.priority) + ' <strong>' + t.daysOverdue + 'd</strong> · ' + emoji + ' ' + t.desc;
      html += '</div>';
    }
    if (critical.length > 5) html += '<p style="margin:6px 0 0;font-size:11px;color:#9b1c1c">…and ' + (critical.length - 5) + ' more critical tasks.</p>';
  }
}
html += '</div>';

// === Q2 ROCKS — dynamic ===
if (liveRocks.length > 0) {
  html += '<div style="padding:16px 20px;background:#f9fafb;margin-top:2px">';
  html += '<h2 style="margin:0 0 12px;font-size:14px;color:#374151;font-weight:700;text-transform:uppercase;letter-spacing:1.5px">🪨 Q2 Rocks — Live Progress</h2>';
  for (const rock of liveRocks) {
    const emoji = areaEmoji[rock.area] || '📌';
    html += '<div style="margin-bottom:12px">';
    html += '<div style="display:flex;justify-content:space-between;align-items:center">';
    html += '<span style="font-size:12px;font-weight:600">' + emoji + ' ' + rock.label + '</span>';
    html += '<span style="font-size:11px;color:#6b7280;margin-left:8px;white-space:nowrap">' + rock.done + '/' + rock.total + ' · ' + rock.pct + '%</span>';
    html += '</div>';
    html += progressBar(rock.pct);
    html += '</div>';
  }
  html += '</div>';
}

// === AREA HEALTH — collapsed ===
html += '<div style="padding:14px 20px;background:white;margin-top:2px">';
html += '<details><summary style="cursor:pointer;font-size:13px;font-weight:600;color:#374151;padding:6px 0">📊 Area health summary (open / done / overdue per domain)</summary>';
html += '<table style="width:100%;border-collapse:collapse;font-size:12px;margin-top:10px">';
html += '<thead><tr style="background:#f3f4f6"><th style="padding:6px;text-align:left">Area</th><th style="padding:6px;text-align:center">Open</th><th style="padding:6px;text-align:center">Done</th><th style="padding:6px;text-align:center">A</th><th style="padding:6px;text-align:center">Due 7d</th><th style="padding:6px;text-align:center">Overdue</th></tr></thead><tbody>';
for (const area of areas) {
  const s = stats[area];
  if (s.total + s.completed === 0) continue;
  const overdueCell = s.overdue > 0
    ? '<span style="color:' + (s.overdue >= 3 ? '#dc2626' : '#ea580c') + ';font-weight:600">' + s.overdue + '</span>'
    : '<span style="color:#16a34a">—</span>';
  const emoji = areaEmoji[area] || '📌';
  html += '<tr style="border-bottom:1px solid #f3f4f6">';
  html += '<td style="padding:6px;text-transform:capitalize">' + emoji + ' ' + area + '</td>';
  html += '<td style="padding:6px;text-align:center">' + s.total + '</td>';
  html += '<td style="padding:6px;text-align:center;color:#16a34a">' + s.completed + '</td>';
  html += '<td style="padding:6px;text-align:center">' + s.priorityA + '</td>';
  html += '<td style="padding:6px;text-align:center">' + s.dueThisWeek + '</td>';
  html += '<td style="padding:6px;text-align:center">' + overdueCell + '</td>';
  html += '</tr>';
}
html += '</tbody></table>';
html += '</details>';
html += '</div>';

// Footer
html += '<div style="background:#1a1a2e;color:#9ca3af;padding:14px 20px;border-radius:0 0 8px 8px;text-align:center;font-size:11px">';
html += 'Life OS Weekly Review · ' + today + ' · Powered by ObsidianHomeOrchestrator';
html += '</div>';
html += '</div>';

const totalDone = areas.reduce((s, a) => s + stats[a].completed, 0);

return [{ json: {
  html, subject, today, weekOf,
  overdueCount: overdueTasks.length,
  criticalCount: critical.length,
  undatedARocksCount: undatedARocks.length,
  liveRocksCount: liveRocks.length,
  totalDone,
  bodyLength: html.length
} }];

const today = new Date().toISOString().split('T')[0];
const log = JSON.stringify({
  workflow: 'weekly-digest-v2',
  run_date: today,
  status: 'success',
  generated_at: new Date().toISOString()
}, null, 2);
return [{ json: { logKey: `99_System/logs/weekly-digest-${today}.json`, logContent: log } }];

const content = $json.logContent;
const key = $json.logKey;
const buf = Buffer.from(content, 'utf-8');
return [{ json: $json, binary: { data: { data: buf.toString('base64'), mimeType: 'application/json', fileName: key.split('/').pop(), fileExtension: 'json', fileSize: buf.length } } }];
